102	    const { selectedStore } = useStore();
103	    const { userProfile } = useAuth();
104	    const [searchTerm, setSearchTerm] = useState("");
105	    const [products, setProducts] = useState<Product[]>([]);
106	    const [open, setOpen] = useState(false);
107	    const [loading, setLoading] = useState(false);
108	
109	    // Vendor Info (Mock for now, future dynamic)
110	    const [vendor, setVendor] = useState("MOMMA");
111	
112	    // Selection States
113	    const [product, setProduct] = useState<Product>(EMPTY_PRODUCT);
114	    const [selectedStorage, setSelectedStorage] = useState<string>("Temperatura Ambiente");
115	    const [responsibleName, setResponsibleName] = useState<string>("");
116	    const [batches, setBatches] = useState<BatchOption[]>([]);
117	    const [selectedBatch, setSelectedBatch] = useState<BatchOption | null>(null);
118	    // Lotes antigos ficam ocultos por padrão para não serem impressos por engano.
