120	    const [embalagens, setEmbalagens] = useState<any[]>([]);
121	    const [selectedEmbalagem, setSelectedEmbalagem] = useState<any>(null);
122	    const [showEmbalagemManager, setShowEmbalagemManager] = useState(false);
123	    // ── Nova modelagem da etiqueta: 3 eixos independentes ──────────────────
