286	
287	    const handlePrint = async () => {
288	        const parsedQuantity = typeof printQuantity === 'string' ? parseInt(printQuantity) : printQuantity;
289	        const numLabels = isNaN(parsedQuantity as number) || (parsedQuantity as number) <= 0 ? 0 : parsedQuantity as number;
290	
291	        if (numLabels <= 0) {
292	            toast({ title: "Atenção", description: "Coloque uma quantidade válida maior que zero.", variant: "destructive" });
293	            return;
294	        }
295	
296	        // Generate unique IDs for each label to print
297	        // Use a fallback for non-secure contexts (like HTTP on local network) where crypto.randomUUID is not available
298	        const newUids = Array.from({ length: numLabels }).map(() => {
299	            if (typeof crypto !== 'undefined' && crypto.randomUUID) {
300	                return crypto.randomUUID().split('-')[0];
301	            }
302	            // Fallback for HTTP connections (e.g. accessing via local IP)
303	            return Math.random().toString(36).substring(2, 10);
304	        });
305	
306	        // Persistir cada UID em etiquetas_qr ANTES de imprimir (rastreabilidade fim-a-fim).
307	        // Apenas para etiqueta de produto — labels "loja"/"aberto" não têm QR rastreável.
308	        if (labelType === "produto" && product.id) {
309	            const { data: { user } } = await supabase.auth.getUser();
310	            const produtoMasterId = parseInt(product.id);
311	            // Fonte da verdade: 3 controles independentes (tipo + unidade + qty).
312	            // selectedEmbalagem é só preset opcional do catálogo (atalho).
313	            const qtyInterna = quantidadeInterna || 1;
314	            const tipoEmb = (tipoEmbalagem || 'caixa').toLowerCase().trim();
315	            const unidadeInt = (unidadeInterna || 'un').toLowerCase().trim();
316	            const lojaOrigem = selectedStore?.id ?? null;
317	
318	            const rows = newUids.map(uid => ({
319	                uid,
320	                produto_master_id: produtoMasterId,
321	                lote_id: selectedBatch?.id || null,
322	                tipo_embalagem: tipoEmb,
323	                embalagem_nome: unidadeInt,
324	                quantidade_interna: qtyInterna,
325	                // Container nasce cheio — saldo disponivel = capacidade inicial.
326	                // Sem isso, RPC bipar_retirada_avulsa recebe NULL e comportamento fica indefinido.
327	                quantidade_disponivel: qtyInterna,
328	                consumida_inteira: false,
329	                produto_nome_snapshot: product.name,
330	                lote_codigo_snapshot: selectedBatch?.codigo || null,
331	                lote_validade_snapshot: selectedBatch?.data_validade || null,
332	                loja_origem_id: lojaOrigem,
333	                loja_atual_id: lojaOrigem,
334	                gerada_por: user?.id ?? null,
335	                gerada_at: new Date().toISOString(),
336	                qr_payload: {
337	                    p: produtoMasterId,
338	                    l: selectedBatch?.id || '',
339	                    c: selectedBatch?.codigo || '',
340	                    n: unidadeInt,
341	                    t: tipoEmb,
342	                    q: qtyInterna,
343	                    u: uid,
344	                },
345	            }));
346	
347	            // eslint-disable-next-line @typescript-eslint/no-explicit-any
348	            const { error } = await (supabase.from('etiquetas_qr' as any) as any).insert(rows);
349	            if (error) {
350	                console.error('[etiquetas_qr] insert falhou:', error);
351	                toast({
352	                    title: "Falha ao registrar etiquetas",
353	                    description: `Impressão abortada para evitar etiqueta órfã. ${error.message}`,
354	                    variant: "destructive",
355	                });
356	                return;
357	            }
