363	
364	    // Esconde lotes antigos da seleção (impressos por engano). Toggle revela todos.
365	    const recentBatches = batches.filter(b => isLoteRecente(b.data_fabricacao, b.created_at));
366	    const hiddenOldCount = batches.length - recentBatches.length;
367	    const visibleBatches = showOldBatches ? batches : recentBatches;
368	
369	    return (
370	        <div className={cn("flex flex-col h-full w-full gap-6 animate-in fade-in duration-500", !isEmbedded && "p-4 md:p-8")}>
