441	                                                e.stopPropagation();
442	                                            }}
443	                                        />
444	                                    </div>
445	                                )}
446	                            </div>
447	
448	                            {/* Product Form - Only show if printing product label */}
449	                            {labelType === "produto" && (
450	                                <div className="space-y-6 animate-in fade-in duration-300">
451	                                    {/* Product Search */}
452	                                    <div className="space-y-4">
453	                                        <Label htmlFor="product-search" className="text-xs uppercase font-bold text-muted-foreground tracking-wider">Produto</Label>
454	                                        <Popover open={open} onOpenChange={setOpen}>
455	                                            <PopoverTrigger asChild>
456	                                                <Button
457	                                                    data-mia-action="abrir-busca-produto"
458	                                                    variant="outline"
459	                                                    role="combobox"
460	                                                    aria-expanded={open}
461	                                                    className="w-full justify-between h-14 rounded-xl text-base border-2 hover:border-[#57715B]/50"
462	                                                >
463	                                                    {product.id ? product.name : "🔍 Buscar produto..."}
464	                                                    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
465	                                                </Button>
466	                                            </PopoverTrigger>
467	                                            <PopoverContent className="w-[300px] p-0 rounded-xl" align="start">
468	                                                <Command>
469	                                                    <CommandInput data-mia-field="buscar_produto" placeholder="Buscar produto..." />
470	                                                    <CommandList>
471	                                                        <CommandEmpty>Nenhum produto encontrado.</CommandEmpty>
472	                                                        <CommandGroup>
473	                                                            {products.map((p) => (
