                                            // chars, redundante com o banco e propenso a perda no Android
                                            // Chrome (bug WontFix de keydown). UID curto e robusto.
                                            value={uid}
                                            size={128}
                                            level="M" // Medium error correction — payload curto comporta
                                            style={{ height: "100%", width: "100%" }}
                                            viewBox={`0 0 256 256`}
                                        />
                                    </div>

                                    {/* Text Right */}
                                    <div className="info-container">
                                        <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
                                            <div style={{ lineHeight: '1.0', marginBottom: '1mm' }}>
                                                <h1 style={{ fontSize: '9pt', fontWeight: 900, textTransform: 'uppercase', marginBottom: '1mm', display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical', overflow: 'hidden', color: 'black' }}>
                                                    {product.name}
                                                </h1>
                                                <div style={{ fontSize: '6pt', fontWeight: 700, textTransform: 'uppercase', border: '2px solid black', display: 'inline-block', padding: '0 2px', borderRadius: '0', color: 'black' }}>
                                                    {selectedStorage}
                                                </div>
                                            </div>

                                            <div style={{ fontSize: '7pt', fontWeight: 700, lineHeight: '1.1', color: 'black', marginTop: '0.5mm' }}>
                                                <div style={{ lineHeight: '1.0', wordBreak: 'break-all' }}>LOT: <span style={{ fontWeight: 900, fontSize: '6pt' }}>{selectedBatch?.codigo ? (selectedBatch.codigo.length === 13 && selectedBatch.codigo.startsWith('L') ? selectedBatch.codigo.substring(0, 9) : selectedBatch.codigo) : '--'}</span></div>
                                                <div style={{ whiteSpace: 'nowrap' }}>VAL: <span style={{ fontWeight: 900 }}>{selectedBatch?.data_validade ? format(new Date(selectedBatch.data_validade + 'T12:00:00'), 'dd/MM/yyyy') : '--/--/----'}</span></div>
                                                <div style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: '26mm' }}>EMB: <span style={{ fontWeight: 900 }}>{selectedEmbalagem?.nome?.substring(0, 10) || 'UN'} ({selectedEmbalagem?.quantidade_interna || 1})</span></div>
                                                <div style={{ whiteSpace: 'nowrap', marginTop: '0.5mm', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: '26mm' }}>RESP: <span style={{ fontWeight: 900 }}>{responsibleName || "User"}</span></div>
                                            </div>
                                        </div>

                                        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', width: '100%', borderTop: '2px solid black', paddingTop: '1mm', marginTop: 'auto' }}>
                                            <img
                                                src="/logo%20sistema/01.%20Reduzida%205.png"
                                                style={{ height: '5mm', objectFit: 'contain', filter: 'grayscale(100%) contrast(2000%)' }}
                                            />
                                        </div>
                                    </div>
                                </div>
                                {index < printUids.length - 1 && <div className="page-break" />}
                            </div>
                        ))}

                        {/* Label 2: Store Name */}
                        {labelType === "loja" && printUids.map((uid, index) => {
                            const storeText = storeLabelText || selectedStore?.shortName || selectedStore?.name || "LOJA";
                            return (
                                <div key={uid} className={cn("label-container", index < printUids.length - 1 ? "page-break" : "")} style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', border: '2px solid black' }}>
                                    <h1 style={{
                                        fontSize: getStoreLabelFontSize(storeText),
                                        fontWeight: 900,
                                        textTransform: 'uppercase',
                                        textAlign: 'center',
                                        lineHeight: 1.15,
                                        wordBreak: 'break-word',
                                        overflowWrap: 'break-word',
                                        whiteSpace: 'pre-line',
                                        width: '100%',
                                        margin: 0,
                                        padding: '0 1mm',
                                    }}>
                                        {storeText}
                                    </h1>
                                </div>
                            );
                        })}

                        {/* Label 3: Produto Aberto */}
                        {labelType === "aberto" && printUids.map((uid, index) => (
                            <div key={uid} className={cn("label-container", index < printUids.length - 1 ? "page-break" : "")} style={{ display: 'flex', flexDirection: 'column', padding: '2mm' }}>
                                <div style={{ width: '100%', height: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', boxSizing: 'border-box', backgroundColor: 'white', color: 'black', fontFamily: 'Arial' }}>
                                    <div style={{ display: 'flex', alignItems: 'flex-end', fontSize: '10pt', fontWeight: 'bold' }}><span style={{ whiteSpace: 'nowrap' }}>Produto:</span><div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '2mm', marginBottom: '1mm' }}></div></div>
                                    <div style={{ display: 'flex', alignItems: 'flex-end', fontSize: '10pt', fontWeight: 'bold' }}><span style={{ whiteSpace: 'nowrap' }}>Fornecedor:</span><div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '2mm', marginBottom: '1mm' }}></div></div>
                                    <div style={{ display: 'flex', alignItems: 'flex-end', fontSize: '10pt', fontWeight: 'bold' }}><span style={{ whiteSpace: 'nowrap' }}>Lote:</span><div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '2mm', marginBottom: '1mm' }}></div></div>
                                    <div style={{ display: 'flex', alignItems: 'flex-end', fontSize: '10pt', fontWeight: 'bold' }}><span style={{ whiteSpace: 'nowrap' }}>Manipulado:</span><div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '2mm', marginRight: '1mm', marginBottom: '1mm' }}></div>/<div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '1mm', marginRight: '1mm', marginBottom: '1mm' }}></div>/<div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '1mm', marginBottom: '1mm' }}></div></div>
                                    <div style={{ display: 'flex', alignItems: 'flex-end', fontSize: '10pt', fontWeight: 'bold' }}><span style={{ whiteSpace: 'nowrap' }}>Validade:</span><div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '2mm', marginRight: '1mm', marginBottom: '1mm' }}></div>/<div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '1mm', marginRight: '1mm', marginBottom: '1mm' }}></div>/<div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '1mm', marginBottom: '1mm' }}></div></div>
                                    <div style={{ display: 'flex', alignItems: 'flex-end', fontSize: '10pt', fontWeight: 'bold' }}><span style={{ whiteSpace: 'nowrap' }}>Responsável:</span><div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '2mm', marginBottom: '1mm' }}></div></div>
                                </div>
                            </div>
                        ))}
                    </div>,
                    document.body
                )
            }
        </div >
    );
}

export default function LabelPrinting() {
    return (
        <div className="min-h-screen bg-gradient-to-b from-gray-100 to-gray-200 dark:from-zinc-900 dark:to-zinc-950">
            <LabelPrintingContent />
        </div>
    );
}

