440	                      variant="ghost"
441	                      size="icon"
442	                      className="h-7 w-7 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800"
443	                      onClick={() =>
444	                        adjustQuantity(
445	                          batch.id,
446	                          batch.quantidade,
447	                          +1,
448	                          batch.lote_id,
449	                        )
450	                      }
451	                    >
452	                      <Plus className="w-3 h-3" />
453	                    </Button>
454	                  </div>
455	                </div>
456	              </div>
457	            );
458	          })
459	        )}
460	      </div>
461	    </div>
462	  );
463	}
