/**
 * Retorna true se o lote é "recente" (dentro da janela).
 *
 * Usa `data_fabricacao` (data de produção) quando presente; senão cai para
 * `created_at`. Sem nenhuma data válida → considera recente (fail-safe: não
 * esconde o lote).
 *
 * Parsing via `'YYYY-MM-DD' + 'T12:00:00'` para evitar shift de fuso (Brasília
 * é UTC-3), seguindo o padrão já usado no resto do código de lotes.
 *
 * @param dataFabricacao - Data de fabricação do lote (string ISO ou null).
 * @param createdAt - created_at do lote, usado como fallback (string ISO ou null).
 * @param windowDays - Tamanho da janela em dias (default {@link LOTE_RECENT_WINDOW_DAYS}).
 */
export function isLoteRecente(
  dataFabricacao?: string | null,
  createdAt?: string | null,
  windowDays: number = LOTE_RECENT_WINDOW_DAYS,
): boolean {
  const ref = dataFabricacao || createdAt;
  if (!ref) return true;

  const refDate = new Date(ref.slice(0, 10) + 'T12:00:00');
  if (Number.isNaN(refDate.getTime())) return true;

  const cutoff = new Date();
  cutoff.setHours(12, 0, 0, 0);
  cutoff.setDate(cutoff.getDate() - (windowDays - 1));

  return refDate.getTime() >= cutoff.getTime();
}

input.new_string:
/**
 * Retorna true se o lote é "recente" (dentro da janela).
 *
 * Recência = atividade recente por QUALQUER das duas datas, usando a MAIS
 * recente delas:
 *   • `created_at` — quando o lote foi REGISTRADO no sistema. Um lote que o
 *     operador acabou de criar tem `created_at` = agora e portanto NUNCA pode
 *     sumir da seleção/gestão, mesmo que a fabricação seja retroativa (produção
 *     de dias anteriores lançada hoje). Esse era exatamente o bug na Fábrica.
 *   • `data_fabricacao` — produção fresca.
 * O objetivo do filtro é esconder lotes ANTIGOS acumulados (registrados há
 * tempo e não tocados), não lotes recém-lançados. Sem nenhuma data válida →
 * recente (fail-safe: não esconde o lote).
 *
 * Parsing via `'YYYY-MM-DD' + 'T12:00:00'` para evitar shift de fuso (Brasília
 * é UTC-3), seguindo o padrão já usado no resto do código de lotes.
 *
 * @param dataFabricacao - Data de fabricação do lote (string ISO ou null).
 * @param createdAt - created_at do lote, quando foi registrado (string ISO ou null).
 * @param windowDays - Tamanho da janela em dias (default {@link LOTE_RECENT_WINDOW_DAYS}).
 */
export function isLoteRecente(
  dataFabricacao?: string | null,
  createdAt?: string | null,
  windowDays: number = LOTE_RECENT_WINDOW_DAYS,
): boolean {
  const cutoff = new Date();
  cutoff.setHours(12, 0, 0, 0);
  cutoff.setDate(cutoff.getDate() - (windowDays - 1));

  // Considera a data MAIS recente entre fabricação e registro: basta uma delas
  // estar dentro da janela para o lote ser "recente". Assim, um lote acabado de
  // registrar (created_at = hoje) aparece sempre, mesmo com fabricação antiga.
  const times = [dataFabricacao, createdAt]
    .filter((d): d is string => Boolean(d))
    .map((d) => new Date(d.slice(0, 10) + 'T12:00:00').getTime())
    .filter((t) => !Number.isNaN(t));

  if (times.length === 0) return true;

  return Math.max(...times) >= cutoff.getTime();
}

